-- Disposable seeded Supabase only. Every fixture and mutation rolls back.
begin;
create extension if not exists pgtap with schema extensions;
select plan(103);
insert into auth.users (id, email) values ('44444444-4444-4444-8444-444444444444', 'rls-seeker-a@example.invalid'), ('55555555-5555-4555-8555-555555555555', 'rls-seeker-b@example.invalid'), ('66666666-6666-4666-8666-666666666666', 'rls-admin@example.invalid');
update public.profiles set role = 'admin' where id = '66666666-6666-4666-8666-666666666666';
update public.jobs set moderation_status = 'pending', boost = null where id = 'bbbbbbbb-0000-0000-0000-000000000001';
insert into public.applications (id, job_id, seeker_id) values ('cccccccc-0000-4000-8000-000000000001', 'bbbbbbbb-0000-0000-0000-000000000006', '44444444-4444-4444-8444-444444444444'), ('cccccccc-0000-4000-8000-000000000002', 'bbbbbbbb-0000-0000-0000-000000000002', '55555555-5555-4555-8555-555555555555');
insert into public.messages (id, application_id, sender_id, body) values ('dddddddd-0000-4000-8000-000000000001', 'cccccccc-0000-4000-8000-000000000001', '44444444-4444-4444-8444-444444444444', 'Private A'), ('dddddddd-0000-4000-8000-000000000002', 'cccccccc-0000-4000-8000-000000000002', '55555555-5555-4555-8555-555555555555', 'Private B');
insert into public.reports (id, reporter_id, job_id, reason) values ('eeeeeeee-0000-4000-8000-000000000001', '44444444-4444-4444-8444-444444444444', 'bbbbbbbb-0000-0000-0000-000000000006', 'spam');
insert into public.audit_logs (id, actor_id, action, entity_type) values ('ffffffff-0000-4000-8000-000000000001', '66666666-6666-4666-8666-666666666666', 'rls.fixture', 'job');

-- Anonymous: real private targets exist before we check non-disclosure.
reset role;
select is((select count(*) from public.jobs where id = 'bbbbbbbb-0000-0000-0000-000000000001'), 1::bigint, 'Anonymous jobs target exists (privileged)');
reset role;
select is((select count(*) from public.companies where id = 'aaaaaaaa-0000-0000-0000-000000000001'), 1::bigint, 'Anonymous companies target exists (privileged)');
reset role;
select is((select count(*) from public.applications where id = 'cccccccc-0000-4000-8000-000000000001'), 1::bigint, 'Anonymous applications target exists (privileged)');
reset role;
select is((select count(*) from public.messages where id = 'dddddddd-0000-4000-8000-000000000001'), 1::bigint, 'Anonymous messages target exists (privileged)');
reset role;
select is((select count(*) from public.reports where id = 'eeeeeeee-0000-4000-8000-000000000001'), 1::bigint, 'Anonymous reports target exists (privileged)');
reset role;
select is((select count(*) from public.audit_logs where id = 'ffffffff-0000-4000-8000-000000000001'), 1::bigint, 'Anonymous audit_logs target exists (privileged)');
reset role;
select is((select count(*) from public.profiles where id = '44444444-4444-4444-8444-444444444444'), 1::bigint, 'Anonymous profiles target exists (privileged)');
reset role;
select set_config('request.jwt.claims', '{}', true);
set local role anon;
select is((select count(*) from public.jobs), 10::bigint, 'anon reads approved California base jobs');
select is((select count(*) from public.public_job_listings), 10::bigint, 'anon reads safe approved California view');
select is((select count(*) from public.public_job_listings where company_name = 'SoCal Trade & Retail Partners'), 7::bigint, 'safe identity includes unverified company with approved jobs');
select is((select count(*) from public.jobs where id = 'bbbbbbbb-0000-0000-0000-000000000001'), 0::bigint, 'anon cannot see pending base job');
select is((select count(*) from public.public_job_listings where id = 'bbbbbbbb-0000-0000-0000-000000000001'), 0::bigint, 'anon cannot see pending view job');
select ok(not has_table_privilege('anon', 'public.companies', 'SELECT'), 'anon has no company base-table select');
select throws_ok($$select owner_id, phone from public.companies$$, '42501', null, 'anon cannot read private company columns');
select throws_ok($$select * from public.applications$$, '42501', null, 'anon cannot read applications');
select throws_ok($$select * from public.profiles$$, '42501', null, 'anon cannot read profiles');
select throws_ok($$select * from public.messages$$, '42501', null, 'anon cannot read messages');
select throws_ok($$select * from public.reports$$, '42501', null, 'anon cannot read reports');
select throws_ok($$select * from public.audit_logs$$, '42501', null, 'anon cannot read audit_logs');
select columns_are('public', 'public_job_listings', array['id','title','category','job_type','city','state','address_display','address_display_mode','pay_min','pay_max','pay_unit','tips_available','schedule_days','schedule_time_range','language_requirement','description','responsibilities','requirements','benefits','moderation_status','boost','posted_at','company_name','company_is_verified','expires_at','updated_at'], 'public view exposes only approved job and safe company identity columns');

-- Seeker: self submission/history, cross-seeker isolation and no escalation.
reset role;
select is((select count(*) from public.applications where id = 'cccccccc-0000-4000-8000-000000000002'), 1::bigint, 'Seeker applications target exists (privileged)');
reset role;
select is((select count(*) from public.messages where id = 'dddddddd-0000-4000-8000-000000000002'), 1::bigint, 'Seeker messages target exists (privileged)');
reset role;
select is((select count(*) from public.profiles where id = '55555555-5555-4555-8555-555555555555'), 1::bigint, 'Seeker profiles target exists (privileged)');
reset role;
select is((select count(*) from public.companies where id = 'aaaaaaaa-0000-0000-0000-000000000001'), 1::bigint, 'Seeker companies target exists (privileged)');
reset role;
select is((select count(*) from public.jobs where id = 'bbbbbbbb-0000-0000-0000-000000000001'), 1::bigint, 'Seeker jobs target exists (privileged)');
reset role;
select is((select count(*) from public.jobs where id = 'bbbbbbbb-0000-0000-0000-000000000006'), 1::bigint, 'Seeker jobs target exists (privileged)');
reset role;
select is((select count(*) from public.profiles where id = '44444444-4444-4444-8444-444444444444'), 1::bigint, 'Seeker profiles target exists (privileged)');
reset role;
select set_config('request.jwt.claims', '{}', true);
select set_config('request.jwt.claims', '{"sub":"44444444-4444-4444-8444-444444444444","role":"authenticated","aal":"aal1"}', true);
set local role authenticated;
select is((select count(*) from public.public_job_listings), 10::bigint, 'signed-in public view remains usable');
select is((select count(*) from public.applications where id = 'cccccccc-0000-4000-8000-000000000001'), 1::bigint, 'seeker sees own application');
select is((select count(*) from public.list_seeker_applications()), 1::bigint, 'seeker history RPC is caller-bound');
select is((select count(*) from public.applications where id = 'cccccccc-0000-4000-8000-000000000002'), 0::bigint, 'seeker cannot see other application');
select is((select count(*) from public.messages where id = 'dddddddd-0000-4000-8000-000000000002'), 0::bigint, 'seeker cannot see other messages');
select is((select count(*) from public.profiles where id = '55555555-5555-4555-8555-555555555555'), 0::bigint, 'seeker cannot see other profile');
select is((select count(*) from public.companies where id = 'aaaaaaaa-0000-0000-0000-000000000001'), 0::bigint, 'seeker cannot read private verified company');
select throws_ok($$insert into public.applications (job_id,seeker_id) values ('bbbbbbbb-0000-0000-0000-000000000001','44444444-4444-4444-8444-444444444444')$$, '42501', null, 'seeker cannot apply to pending job');
select throws_ok($$insert into public.applications (job_id,seeker_id) values ('bbbbbbbb-0000-0000-0000-000000000006','44444444-4444-4444-8444-444444444444')$$, '23505', null, 'duplicate application rejected');
select throws_ok($$insert into public.applications (job_id,seeker_id) values ('bbbbbbbb-0000-0000-0000-000000000006','55555555-5555-4555-8555-555555555555')$$, '42501', null, 'seeker cannot submit as someone else');
select lives_ok($$insert into public.applications (job_id,seeker_id) values ('bbbbbbbb-0000-0000-0000-000000000002','44444444-4444-4444-8444-444444444444')$$, 'seeker creates own approved-job application');
select is((select count(*) from public.list_seeker_applications()), 2::bigint, 'new application appears in own history');
select throws_ok($$update public.profiles set role = 'employer' where id = '44444444-4444-4444-8444-444444444444'$$, 'P0001', null, 'seeker cannot self-promote to employer');
select throws_ok($$update public.profiles set role = 'admin' where id = '44444444-4444-4444-8444-444444444444'$$, 'P0001', null, 'seeker cannot self-promote to admin');
select lives_ok($$insert into public.messages (application_id,sender_id,body) values ('cccccccc-0000-4000-8000-000000000001','44444444-4444-4444-8444-444444444444','Own thread')$$, 'seeker sends to own thread');
select throws_ok($$insert into public.messages (application_id,sender_id,body) values ('cccccccc-0000-4000-8000-000000000002','44444444-4444-4444-8444-444444444444','Other thread')$$, '42501', null, 'seeker cannot write another thread');

-- Employer A: full own-company access and own applicants, never B records.
reset role;
select is((select count(*) from public.companies where id = 'aaaaaaaa-0000-0000-0000-000000000002'), 1::bigint, 'Employer companies target exists (privileged)');
reset role;
select is((select count(*) from public.jobs where id = 'bbbbbbbb-0000-0000-0000-000000000001'), 1::bigint, 'Employer jobs target exists (privileged)');
reset role;
select is((select count(*) from public.profiles where id = '22222222-2222-2222-2222-222222222222'), 1::bigint, 'Employer profiles target exists (privileged)');
reset role;
select is((select count(*) from public.applications where id = 'cccccccc-0000-4000-8000-000000000002'), 1::bigint, 'Employer applications target exists (privileged)');
reset role;
select is((select count(*) from public.messages where id = 'dddddddd-0000-4000-8000-000000000002'), 1::bigint, 'Employer messages target exists (privileged)');
reset role;
select is((select count(*) from public.companies where id = 'aaaaaaaa-0000-0000-0000-000000000001'), 1::bigint, 'Employer companies target exists (privileged)');
reset role;
select is((select count(*) from public.reports where id = 'eeeeeeee-0000-4000-8000-000000000001'), 1::bigint, 'Employer reports target exists (privileged)');
reset role;
select is((select count(*) from public.audit_logs where id = 'ffffffff-0000-4000-8000-000000000001'), 1::bigint, 'Employer audit_logs target exists (privileged)');
reset role;
select set_config('request.jwt.claims', '{}', true);
select set_config('request.jwt.claims', '{"sub":"11111111-1111-1111-1111-111111111111","role":"authenticated","aal":"aal1"}', true);
set local role authenticated;
select is((select count(*) from (select owner_id,phone from public.companies where id = 'aaaaaaaa-0000-0000-0000-000000000001') c), 1::bigint, 'owner reads full own company');
with changed as (update public.companies set phone = 'fictional-test-phone' where id = 'aaaaaaaa-0000-0000-0000-000000000001' returning id) select is((select count(*) from changed), 1::bigint, 'owner updates own company');
select is((select count(*) from public.companies where id = 'aaaaaaaa-0000-0000-0000-000000000002'), 0::bigint, 'owner cannot read other company');
with changed as (update public.companies set phone = 'unauthorized' where id = 'aaaaaaaa-0000-0000-0000-000000000002' returning id) select is((select count(*) from changed), 0::bigint, 'owner cannot update other company');
select is((select count(*) from public.jobs where id = 'bbbbbbbb-0000-0000-0000-000000000001'), 1::bigint, 'owner sees own pending job');
with changed as (update public.jobs set title = 'Owner edited pending job' where id = 'bbbbbbbb-0000-0000-0000-000000000001' returning id) select is((select count(*) from changed), 1::bigint, 'owner edits own pending job');
select throws_ok($$update public.jobs set moderation_status = 'approved' where id = 'bbbbbbbb-0000-0000-0000-000000000001'$$, '42501', null, 'owner cannot approve own job');
select throws_ok($$update public.companies set is_verified = false where id = 'aaaaaaaa-0000-0000-0000-000000000001'$$, '42501', null, 'owner cannot change verification');
select is((select count(*) from public.applications where id = 'cccccccc-0000-4000-8000-000000000001'), 1::bigint, 'owner sees own applicant');
select is((select count(*) from public.list_employer_applications() where application_id = 'cccccccc-0000-4000-8000-000000000001'), 1::bigint, 'owner applicant RPC still works');
select is((select count(*) from public.applications where id = 'cccccccc-0000-4000-8000-000000000002'), 0::bigint, 'owner cannot read other employer applicant');
select is((select count(*) from public.list_employer_applications() where application_id = 'cccccccc-0000-4000-8000-000000000002'), 0::bigint, 'RPC hides other employer applicant');
select is((select count(*) from public.messages where id = 'dddddddd-0000-4000-8000-000000000002'), 0::bigint, 'owner cannot read other employer messages');
select throws_ok($$insert into public.messages (application_id,sender_id,body) values ('cccccccc-0000-4000-8000-000000000002','11111111-1111-1111-1111-111111111111','Other employer thread')$$, '42501', null, 'owner cannot write other employer messages');
select lives_ok($$insert into public.messages (application_id,sender_id,body) values ('cccccccc-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','Employer reply')$$, 'owner can message own applicant');
select is((select count(*) from public.reports where id = 'eeeeeeee-0000-4000-8000-000000000001'), 0::bigint, 'owner cannot identify reporter');
select is((select count(*) from public.audit_logs where id = 'ffffffff-0000-4000-8000-000000000001'), 0::bigint, 'owner cannot read audit log');
reset role;
select is((select count(*) from public.jobs where id = 'bbbbbbbb-0000-0000-0000-000000000001'), 1::bigint, 'Employer B pending job target exists (privileged)');
reset role;
select is((select count(*) from public.profiles where id = '11111111-1111-1111-1111-111111111111'), 1::bigint, 'Employer B private profile target exists (privileged)');
reset role;
select set_config('request.jwt.claims', '{}', true);
select set_config('request.jwt.claims', '{"sub":"22222222-2222-2222-2222-222222222222","role":"authenticated","aal":"aal1"}', true);
set local role authenticated;
select is((select count(*) from public.jobs where id = 'bbbbbbbb-0000-0000-0000-000000000001'), 0::bigint, 'other employer cannot read private job');
select is((select count(*) from public.profiles where id = '11111111-1111-1111-1111-111111111111'), 0::bigint, 'other employer cannot read private profile');

-- Admin: A3 does not yet enforce AAL2; A4 adds the negative AAL1 mutation case.
reset role;
select set_config('request.jwt.claims', '{}', true);
select set_config('request.jwt.claims', '{"sub":"66666666-6666-4666-8666-666666666666","role":"authenticated","aal":"aal1"}', true);
set local role authenticated;
select is((select count(*) from public.profiles where id = '66666666-6666-4666-8666-666666666666'), 1::bigint, 'admin aal1 reads own security profile');
reset role;
select set_config('request.jwt.claims', '{}', true);
select set_config('request.jwt.claims', '{"sub":"66666666-6666-4666-8666-666666666666","role":"authenticated","aal":"aal2"}', true);
set local role authenticated;
select is((select count(*) from public.companies), 3::bigint, 'admin aal2 reads all companies');
select is((select count(*) from (select owner_id,phone from public.companies where id = 'aaaaaaaa-0000-0000-0000-000000000001') c), 1::bigint, 'admin reads private company fields');
with changed as (update public.companies set phone = 'admin-test-phone' where id = 'aaaaaaaa-0000-0000-0000-000000000002' returning id) select is((select count(*) from changed), 1::bigint, 'admin updates other company');
with changed as (update public.jobs set moderation_status = 'approved' where id = 'bbbbbbbb-0000-0000-0000-000000000001' returning id) select is((select count(*) from changed), 1::bigint, 'admin approves pending job');
select is((select count(*) from public.applications where id = 'cccccccc-0000-4000-8000-000000000001'), 1::bigint, 'admin reads applicants');
select is((select count(*) from public.messages where id = 'dddddddd-0000-4000-8000-000000000001'), 1::bigint, 'admin reads application messages');
select is((select count(*) from public.reports where id = 'eeeeeeee-0000-4000-8000-000000000001'), 1::bigint, 'admin reads report and reporter');
with changed as (update public.reports set status = 'reviewed' where id = 'eeeeeeee-0000-4000-8000-000000000001' returning id) select is((select count(*) from changed), 1::bigint, 'admin reviews report');
select is((select count(*) from public.audit_logs where id = 'ffffffff-0000-4000-8000-000000000001'), 1::bigint, 'admin reads audit log');

-- Forging metadata or AAL without a subject never supplies a DB admin identity.
reset role;
select is((select count(*) from public.reports where id = 'eeeeeeee-0000-4000-8000-000000000001'), 1::bigint, 'Missing subject report target exists (privileged)');
reset role;
select is((select count(*) from public.audit_logs where id = 'ffffffff-0000-4000-8000-000000000001'), 1::bigint, 'Missing subject audit target exists (privileged)');
reset role;
select set_config('request.jwt.claims', '{}', true);
set local role authenticated;
select set_config('request.jwt.claims', '{"role":"authenticated","aal":"aal2","user_metadata":{"role":"admin"}}', true);
select ok(not public.is_admin(), 'aal2 and user metadata do not create admin identity');
select is((select count(*) from public.reports where id = 'eeeeeeee-0000-4000-8000-000000000001'), 0::bigint, 'missing subject cannot read admin report');
with changed as (update public.reports set status = 'dismissed' where id = 'eeeeeeee-0000-4000-8000-000000000001' returning id) select is((select count(*) from changed), 0::bigint, 'missing subject cannot review report');
select is((select count(*) from public.audit_logs where id = 'ffffffff-0000-4000-8000-000000000001'), 0::bigint, 'missing subject cannot read audit log');

-- Demotion: retained ownership cannot preserve employer writes or applicant access.
reset role;
select set_config('request.jwt.claims', '{}', true);
set local role postgres;
update public.profiles set role = 'seeker' where id = '11111111-1111-1111-1111-111111111111';
reset role;
select is((select count(*) from public.companies where id = 'aaaaaaaa-0000-0000-0000-000000000001'), 1::bigint, 'Demoted companies target exists (privileged)');
reset role;
select is((select count(*) from public.jobs where id = 'bbbbbbbb-0000-0000-0000-000000000001'), 1::bigint, 'Demoted jobs target exists (privileged)');
reset role;
select is((select count(*) from public.applications where id = 'cccccccc-0000-4000-8000-000000000001'), 1::bigint, 'Demoted applications target exists (privileged)');
reset role;
select is((select count(*) from public.messages where id = 'dddddddd-0000-4000-8000-000000000001'), 1::bigint, 'Demoted messages target exists (privileged)');
reset role;
select is((select count(*) from public.profiles where id = '11111111-1111-1111-1111-111111111111'), 1::bigint, 'Demoted profiles target exists (privileged)');
reset role;
select set_config('request.jwt.claims', '{}', true);
select set_config('request.jwt.claims', '{"sub":"11111111-1111-1111-1111-111111111111","role":"authenticated","aal":"aal1"}', true);
set local role authenticated;
select is((select count(*) from public.profiles where id = '11111111-1111-1111-1111-111111111111'), 1::bigint, 'demoted user retains own profile');
select is((select count(*) from public.companies where id = 'aaaaaaaa-0000-0000-0000-000000000001'), 0::bigint, 'demoted employer cannot read private company');
select is((select count(*) from public.applications where id = 'cccccccc-0000-4000-8000-000000000001'), 0::bigint, 'demoted employer cannot read former applicants');
select is((select count(*) from public.list_employer_applications()), 0::bigint, 'demoted employer RPC returns no applicants');
select is((select count(*) from public.messages where id = 'dddddddd-0000-4000-8000-000000000001'), 0::bigint, 'demoted employer cannot read former messages');
with changed as (update public.companies set phone = 'demoted-write' where id = 'aaaaaaaa-0000-0000-0000-000000000001' returning id) select is((select count(*) from changed), 0::bigint, 'demoted employer cannot update company');
with changed as (update public.jobs set moderation_status = 'pending' where id = 'bbbbbbbb-0000-0000-0000-000000000001' returning id) select is((select count(*) from changed), 0::bigint, 'demoted employer cannot update owned job');
select throws_ok($$insert into public.companies (owner_id,name,city) values ('11111111-1111-1111-1111-111111111111','Denied company','LA')$$, '42501', null, 'demoted employer cannot create company');
select throws_ok($$insert into public.jobs (company_id,title,category,job_type,city,pay_min,pay_max,pay_unit,schedule_days,schedule_time_range,language_requirement,description) values ('aaaaaaaa-0000-0000-0000-000000000001','Denied job','retail','part_time','LA',20,22,'hour','Mon','9-5','english_required','Denied')$$, '42501', null, 'demoted employer cannot create job from old ownership');
select throws_ok($$insert into public.messages (application_id,sender_id,body) values ('cccccccc-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','Denied')$$, '42501', null, 'demoted employer cannot send former applicant message');
select * from finish();
rollback;
